"""M6 synthetic protocol tests; actual boot evidence is generated by qemu.py."""
import unittest
from m6_validation import expected_order, validate_m6, benchmark_markdown


def fixture():
    lines = ['M6CONFIG samples=8 warmups=1 sizes=2 conditions=22 runs=198 kernel_image_bytes=1048576 raw_metadata=1024 object_metadata=24384 reserved_bench_bytes=25408 task_context_bytes=400 fence_min=20 file_pages=0 compressed_bytes=0 timed_serial=0']
    for pages, dirty, mode, sample, order in expected_order():
        lines.extend(['M6TASK task=0 root=0x1000 code=0x2000 stack=0x3000 attack=0',
                      'M6TASK task=1 root=0x5000 code=0x6000 stack=0x7000 attack=0'])
        faults = dirty if mode in [2, 4] else 0
        payload = pages * 2 if mode == 0 else pages + faults
        total = 4096 * pages * (pages + 1) // 2
        row = dict(pages=pages, dirty=dirty, mode=mode, round=sample, order=order,
                   warmup=int(sample == 0), root0=4096, root1=20480, cs0=3, cs1=3,
                   input_sum=total, writer_sum=total + dirty * 255 - dirty * (dirty + 1),
                   reader_sum=total, payload_peak=payload, pool_peak=89 + 19 + payload,
                   before=89, after=89, extra_tables=14, task_frames=5, mapping_pages=pages * 2,
                   final_tables=73, final_mappings=30000, metadata=24384 if mode >= 3 else 1024,
                   faults=faults, copies=pages if mode == 0 else faults, calls=6,
                   create_ticks=10000 if sample == 0 else 100 + sample, map_ticks=200,
                   read_ticks=300, write_read_ticks=400, handler_ticks=10 * faults,
                   handler_max=10 if faults else 0, unmap_ticks=200, release_ticks=100,
                   isolation=1, cleanup=1)
        lines.append('M6RUN ' + ' '.join(f'{key}={value}' for key, value in row.items()))
    lines.extend(['M6CHECK measured=176 warmups=22 peak_tracking=1 checksum=1 physical_identity=1 isolation=1 cleanup=1', 'M6 PASS', ''])
    return '\n'.join(lines)


class M6ValidatorTests(unittest.TestCase):
    @classmethod
    def setUpClass(cls):
        cls.serial = fixture()
        cls.m2 = {'allocated_frames': 89, 'table_frames': 73, 'virtual_mappings': 30000}

    def test_accepts_all_modes_and_excludes_only_labelled_warmups(self):
        result = validate_m6(self.serial, self.m2)
        self.assertEqual(len(result['runs']), 198)
        self.assertEqual(len(result['summary']), 22)
        for group in result['summary']:
            self.assertEqual(group['samples'], 8)
            self.assertEqual(group['timing_ticks']['create_ticks'], dict(min=101, median=104.5, max=108))
        self.assertIn('eager-private', benchmark_markdown(result))
        self.assertEqual(result['summary'][0]['read_bytes_per_million_ticks']['median'], 4 * 4096 * 2 * 1000000 / 300)

    def test_rejects_marker_only_and_incomplete_matrix(self):
        for serial in ['M5 PASS\n', 'M6 PASS\n', self.serial.replace('M6RUN ', 'OMITTED ', 1),
                       self.serial + self.serial, self.serial.replace('round=1', 'round=0', 1)]:
            with self.assertRaises(ValueError):
                validate_m6(serial, self.m2)

    def test_rejects_forged_peaks_copy_counts_and_leaks(self):
        for old, new in [('payload_peak=8', 'payload_peak=4'), ('pool_peak=116', 'pool_peak=89'),
                         ('copies=4', 'copies=0'), ('faults=1', 'faults=0'),
                         ('after=89', 'after=90'), ('final_tables=73', 'final_tables=74'),
                         ('mapping_pages=8', 'mapping_pages=4')]:
            with self.subTest(old=old), self.assertRaises(ValueError):
                validate_m6(self.serial.replace(old, new, 1), self.m2)

    def test_rejects_invalid_authority_and_data_evidence(self):
        for old, new in [('cs0=3', 'cs0=0'), ('root1=20480', 'root1=4096'),
                         ('reader_sum=40960', 'reader_sum=40961'),
                         ('writer_sum=41213', 'writer_sum=40960'), ('M6TASK ', 'OMITTED ')]:
            with self.subTest(old=old), self.assertRaises(ValueError):
                validate_m6(self.serial.replace(old, new, 1), self.m2)

    def test_rejects_time_accounting_and_warmup_manipulation(self):
        for old, new in [('read_ticks=300', 'read_ticks=0'), ('warmup=1', 'warmup=0'),
                         ('handler_ticks=10 ', 'handler_ticks=0 '), ('handler_max=0', 'handler_max=1'),
                         ('timed_serial=0', 'timed_serial=1'), ('samples=8', 'samples=7')]:
            with self.subTest(old=old), self.assertRaises(ValueError):
                validate_m6(self.serial.replace(old, new, 1), self.m2)

    def test_rejects_hidden_metadata_and_bad_resident_scope(self):
        for old, new in [('raw_metadata=1024', 'raw_metadata=0'), ('metadata=24384', 'metadata=1024'),
                         ('reserved_bench_bytes=25408', 'reserved_bench_bytes=1024'),
                         ('kernel_image_bytes=1048576', 'kernel_image_bytes=1')]:
            with self.subTest(old=old), self.assertRaises(ValueError):
                validate_m6(self.serial.replace(old, new, 1), self.m2)
